use EIPSI\AssessmentEditor\Runtime as N;
wp_set_current_user(1);$owner=new N\Owner();$cases=array();$failed=0;$owned=array();$priorCron=_get_cron_array();$priorEnabled=get_option('eipsi_native_runtime_enabled',null);
function c3_assert($v,$message='Assertion failed'){if(!$v)throw new RuntimeException($message);}
function c3_test($name,$fn){global$cases;$cases[$name]=$fn;}
function c3_http($path,$body=null,$cookie=null){global$c3cookie;$args=array('timeout'=>20,'redirection'=>0,'headers'=>array('Host'=>'127.0.0.1:18080'),'cookies'=>array($cookie??$c3cookie));if($body!==null){$args['method']='POST';$args['body']=$body;}$r=wp_remote_request('http://127.0.0.1'.$path,$args);c3_assert(!is_wp_error($r),'HTTP failed');return array('status'=>wp_remote_retrieve_response_code($r),'body'=>wp_remote_retrieve_body($r),'headers'=>wp_remote_retrieve_headers($r));}
function c3_ajax($id,$payload){$r=c3_http('/wp-admin/admin-ajax.php',array('action'=>'eipsi_native_participant','execution'=>$id,'payload'=>wp_json_encode($payload)));$r['json']=json_decode($r['body'],true);return$r;}
function c3_view($id){$r=c3_ajax($id,array('action'=>'view'));c3_assert($r['status']===200,$r['body']);return$r['json']['data'];}
function c3_meta($f){$m=$f['session']['metadata']??array('contract'=>'NATIVE_PROCESS_V1','assessment_id'=>$f['definition']['id'],'definition_ref'=>array(),'started_at'=>1000,'completed_at'=>null,'duration'=>0,'status'=>'active','recovery_used'=>false,'recovery_count'=>0,'pages'=>array(),'items'=>array(),'events'=>array(),'dropped_events'=>0);if($f['randomization']!==null)$m['randomization']=$f['randomization'];return$m;}
function c3_command($f,$action,$answers=null,$metadata=null){return c3_ajax($f['execution_id'],array('action'=>$action,'command_id'=>'C3_'.bin2hex(random_bytes(12)),'revision'=>$f['revision'],'version_id'=>$f['version_id'],'csrf'=>$f['csrf'],'answers'=>$answers??($f['session']['answers']??array()),'touched'=>array(),'metadata'=>$metadata??c3_meta($f)));}
function c3_new($contract=null){global$owner,$owned;$d=json_decode(file_get_contents(__DIR__.'/assessment-editor/randomization-fixture.json'),true);$base=json_decode(file_get_contents(__DIR__.'/assessment-editor/functional-fixture.json'),true);$d['id']='AE_SEC3_'.bin2hex(random_bytes(10));$d['flow']['pages']=array();$d['flow']['metadata_profile']='basic';$random=$d['elements'][0];$random['properties']['count']=1;foreach($random['children']as$i=>&$child)$child['properties']['label']='SEC3_SECRET_'.($i===0?'A':'B_'.$i).'_'.bin2hex(random_bytes(5));unset($child);$intro=$base['elements'][0];$intro['properties']['required']=false;$intro['properties']['label']='SEC3_VISIBLE_INTRO';$break=$base['elements'][3];$d['elements']=array($intro,$break,$random);$d=D::validate($d);R::save($d,0);$owned[]=$d['id'];$v=$owner->publish($d['id'],1);$a=$owner->assign($v['version_id'],array('kind'=>'WORDPRESS_USER','user_id'=>1));$stored=json_decode($owner->store->find('executions',$a['execution_id'])['metadata_json'],true)['randomization'];if($contract==='V1')$stored['contract']='LOCAL_RANDOMIZATION_V1';if($contract==='V3')$stored=EIPSI\AssessmentEditor\Randomization::lazy(time()*1000);if($contract!==null)$owner->store->update('executions',array('metadata_json'=>D::json(array('randomization'=>$stored))),$owner->store->prepare('id=%s',$a['execution_id']));return array('id'=>$a['execution_id'],'definition'=>$d,'random'=>$stored,'version'=>$v);}
$sessionToken=WP_Session_Tokens::get_instance(1)->create(time()+3600);$c3cookie=new WP_Http_Cookie(array('name'=>LOGGED_IN_COOKIE,'value'=>wp_generate_auth_cookie(1,time()+3600,'logged_in',$sessionToken)));
c3_test('Initial participant HTML contains no future candidate content',function(){$x=c3_new();$r=c3_http('/?eipsi_native='.$x['id']);c3_assert($r['status']===200);c3_assert(strpos($r['body'],'SEC3_VISIBLE_INTRO')!==false);c3_assert(strpos($r['body'],'SEC3_SECRET_')===false,'Future candidate content leaked in initial HTML');});
c3_test('AJAX recovery contains no future candidate content',function(){$x=c3_new();$f=c3_view($x['id']);c3_assert(strpos(D::json($f),'SEC3_SECRET_')===false&&strpos(D::json($f),$x['definition']['flow']['pages'][1]['id'])===false,'Future content or semantic page identity leaked in AJAX view');});
c3_test('Participant payload contains neither raw nor encoded seed',function(){$x=c3_new();$body=D::json(c3_view($x['id']));foreach(array($x['random']['seed'],base64_encode($x['random']['seed']),bin2hex($x['random']['seed']))as$secret)c3_assert(strpos($body,$secret)===false,'Native seed leaked');});
c3_test('Participant cannot submit a selected but not yet shown future question',function(){$x=c3_new();$f=c3_view($x['id']);$selected=$x['random']['blocks']['EL_RANDOM_TEST']['order'][0];$q=null;foreach($x['definition']['elements'][2]['children']as$c)if($c['id']===$selected)$q=$c;c3_assert($q!==null);$answer=in_array($q['type'],array('single_choice','select','likert'),true)?$q['options'][0]['id']:'forged future';$r=c3_command($f,'partial',array($q['response_key']=>$answer));c3_assert($r['status']===400,'Future answer was accepted');});
c3_test('Reaching randomization delivers selected content and never unselected content',function(){$x=c3_new();$f=c3_view($x['id']);$r=c3_command($f,'next');c3_assert($r['status']===200,$r['body']);$f=$r['json']['data'];$selected=$x['random']['blocks']['EL_RANDOM_TEST']['order'];$body=D::json($f);foreach($x['definition']['elements'][2]['children']as$c)c3_assert((strpos($body,$c['properties']['label'])!==false)===in_array($c['id'],$selected,true),'Wrong candidate visibility');});
c3_test('Forged randomization reference is rejected without changing server outcome',function()use($owner){$x=c3_new();$f=c3_view($x['id']);$m=c3_meta($f);$m['randomization']['seed']='FORGED';$before=$owner->store->find('executions',$x['id']);$r=c3_command($f,'open',null,$m);c3_assert($r['status']===409,'Forged record accepted');c3_assert($owner->store->find('executions',$x['id'])===$before,'Rejected forgery changed state');});
c3_test('Participant projection preserves immutable server snapshot and complete provenance',function()use($owner){$x=c3_new();c3_view($x['id']);$v=$owner->store->find('versions',$x['version']['version_id']);c3_assert(hash('sha256',$v['definition_json'])===$v['definition_hash']);$m=json_decode($owner->store->find('executions',$x['id'])['metadata_json'],true);c3_assert($m['randomization']===$x['random']);c3_assert(strpos($v['definition_json'],'SEC3_SECRET_')!==false);});
c3_test('Participant responses are private and not publicly cacheable',function(){$x=c3_new();$r=c3_http('/?eipsi_native='.$x['id']);$cache=$r['headers']['cache-control']??'';c3_assert(strpos($cache,'no-store')!==false&&strpos($cache,'private')!==false,'Missing private/no-store');});

c3_test('Back and recovery never reintroduce unselected candidates',function(){$x=c3_new();$f=c3_view($x['id']);$r=c3_command($f,'next');c3_assert($r['status']===200,$r['body']);$f=$r['json']['data'];$r=c3_command($f,'back');c3_assert($r['status']===200,$r['body']);$f=c3_view($x['id']);c3_assert($f['page']===0);$selected=$x['random']['blocks']['EL_RANDOM_TEST']['order'];foreach($x['definition']['elements'][2]['children']as$c)if(!in_array($c['id'],$selected,true))c3_assert(strpos(D::json($f),$c['properties']['label'])===false,'Recovery disclosed alternative');});
c3_test('Forged future page metadata is rejected',function(){$x=c3_new();$f=c3_view($x['id']);$m=c3_meta($f);$id=$x['definition']['flow']['pages'][1]['id'];$m['pages'][$id]=array('page_id'=>$id,'presented_at'=>1000);$r=c3_command($f,'open',null,$m);c3_assert($r['status']===400,'Future page metadata accepted');});
c3_test('No analytical option values or full randomization configuration in participant definition',function(){$x=c3_new();$f=c3_command(c3_view($x['id']),'next')['json']['data'];$walk=function($items)use(&$walk){foreach($items as$item){c3_assert(!isset($item['randomization'])&&!isset($item['properties']['randomize_options']));foreach($item['options']as$option)c3_assert(!array_key_exists('value',$option)&&!array_key_exists('fixed',$option));$walk($item['children']);}};$walk($f['definition']['elements']);c3_assert(!isset($f['definition']['authoring']),'Authoring metadata exposed');$body=D::json($f['randomization']);foreach(array('seed','candidates','eligible','weights','control')as$forbidden)c3_assert(strpos($body,'"'.$forbidden.'"')===false,'Scientific config exposed');});
c3_test('Completed page receives completion content only after submission',function(){$x=c3_new();$f=c3_view($x['id']);c3_assert($f['definition']['flow']['completion']['message_html']==='');$f=c3_command($f,'next')['json']['data'];$q=$f['definition']['elements'][1]??null;$answers=array();$walk=function($items)use(&$walk,&$answers){foreach($items as$q){if($q['response_key']){$answers[$q['response_key']]=in_array($q['type'],array('single_choice','select','likert'),true)?$q['options'][0]['id']:'response';}$walk($q['children']);}};$walk($f['definition']['elements']);$r=c3_command($f,'submit',$answers);c3_assert($r['status']===200,$r['body']);c3_assert($r['json']['data']['state']==='COMPLETED'&&$r['json']['data']['definition']['flow']['completion']['message_html']!=='');});
c3_test('Protected media uses DB bytes and author preview requires administrative permission',function(){global$c3cookie;$bytes=base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+j6XcAAAAASUVORK5CYII=');$file=wp_tempnam();file_put_contents($file,$bytes);try{$url=N\PrivateMedia::pin($file,'image/png','png');$path='/?'.parse_url($url,PHP_URL_QUERY);$r=c3_http($path);c3_assert($r['status']===200&&$r['body']===$bytes);$r=c3_http($path,null,new WP_Http_Cookie(array('name'=>'none','value'=>'none')));c3_assert($r['status']===404,'Unauthenticated static-like media access');$upload=wp_upload_dir();c3_assert(!file_exists($upload['basedir'].'/eipsi-native-media/'.N\PrivateMedia::key($url)),'Created static copy');}finally{unlink($file);}});
c3_test('Protected participant media checks selection ownership and expired capability',function()use($owner,&$owned){$base=json_decode(file_get_contents(__DIR__.'/assessment-editor/functional-fixture.json'),true);$upload=wp_upload_dir();wp_mkdir_p($upload['basedir']);$name='sec3-image-'.bin2hex(random_bytes(5)).'.png';$file=$upload['basedir'].'/'.$name;file_put_contents($file,base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+j6XcAAAAASUVORK5CYII='));try{$base['id']='AE_SEC3_MEDIA_'.bin2hex(random_bytes(8));$base['flow']['pages']=array();$base['elements']=array($base['elements'][0]);$base['elements'][0]['properties']['label_html']='<p>Visible <img src="'.$upload['baseurl'].'/'.$name.'"></p>';$base=D::validate($base);R::save($base,0);$owned[]=$base['id'];$v=$owner->publish($base['id'],1);$a=$owner->assign($v['version_id'],array('kind'=>'WORDPRESS_USER','user_id'=>1));$f=c3_view($a['execution_id']);$html=$f['definition']['elements'][0]['properties']['label_html'];$tags=new WP_HTML_Tag_Processor($html);c3_assert($tags->next_tag('IMG'));$url=$tags->get_attribute('src');$path='/?'.parse_url($url,PHP_URL_QUERY);$r=c3_http($path);c3_assert($r['status']===200,'Selected authorized image denied');$r=c3_http($path,null,new WP_Http_Cookie(array('name'=>'none','value'=>'none')));c3_assert($r['status']===404,'Wrong owner could read image');parse_str(parse_url($url,PHP_URL_QUERY),$q);$q['expires']=time()-1;$q['signature']=hash_hmac('sha256',$a['execution_id'].'|'.$q['eipsi_native_asset'].'|'.$q['expires'],wp_salt('auth'));$r=c3_http('/?'.http_build_query($q));c3_assert($r['status']===404,'Expired capability accepted');$q['expires']=time()+300;$other=wp_tempnam();file_put_contents($other,file_get_contents($file).'SEC3_UNSELECTED');try{$hidden=N\PrivateMedia::pin($other,'image/png','png');}finally{unlink($other);}$q['eipsi_native_asset']=N\PrivateMedia::key($hidden);$q['signature']=hash_hmac('sha256',$a['execution_id'].'|'.$q['eipsi_native_asset'].'|'.$q['expires'],wp_salt('auth'));c3_assert(c3_http('/?'.http_build_query($q))['status']===404,'Existing unselected asset accepted');}finally{unlink($file);}});

foreach(array('V1','V3')as$contract)c3_test($contract.' hides seed and future candidates without changing stored decisions',function()use($contract,$owner){$x=c3_new($contract);$f=c3_view($x['id']);$text=D::json($f);c3_assert(strpos($text,'SEC3_SECRET_')===false&&strpos($text,$x['random']['seed'])===false);$before=json_decode($owner->store->find('executions',$x['id'])['metadata_json'],true)['randomization'];if($contract==='V3')c3_assert(!$before['blocks'],'Projection resolved future lazy draw');$r=c3_command($f,'next');c3_assert($r['status']===200,$r['body']);$f=$r['json']['data'];$record=json_decode($owner->store->find('executions',$x['id'])['metadata_json'],true)['randomization'];c3_assert($record['seed']===$x['random']['seed']);$selected=$record['blocks']['EL_RANDOM_TEST']['order'];foreach($x['definition']['elements'][2]['children']as$c)c3_assert((strpos(D::json($f),$c['properties']['label'])!==false)===in_array($c['id'],$selected,true));});
c3_test('Forged unselected answer is rejected after selection as well as before',function(){$x=c3_new();$f=c3_command(c3_view($x['id']),'next')['json']['data'];$selected=$x['random']['blocks']['EL_RANDOM_TEST']['order'];$q=null;foreach($x['definition']['elements'][2]['children']as$c)if(!in_array($c['id'],$selected,true)){$q=$c;break;}$r=c3_command($f,'partial',array($q['response_key']=>'forged'));c3_assert($r['status']===400,'Unselected answer accepted');c3_assert(strpos($r['body'],$q['properties']['label'])===false,'Error revealed hidden label');});
c3_test('Projection is read-only and bounded compared with author snapshot',function()use($owner){$x=c3_new();$raw=$owner->view($x['id']);$before=$owner->store->find('executions',$x['id']);$start=microtime(true);for($i=0;$i<100;$i++)$p=N\EffectiveAssessmentProjection::frame($raw);$elapsed=microtime(true)-$start;c3_assert($elapsed<2,'Projection exceeded 20ms average on small fixture');c3_assert(strlen(D::json($p))<strlen(D::json($raw)),'Projection did not reduce payload');c3_assert($owner->store->find('executions',$x['id'])===$before,'Pure projection wrote execution');echo 'METRIC SEC3 projection100_seconds='.round($elapsed,6).' raw_bytes='.strlen(D::json($raw)).' participant_bytes='.strlen(D::json($p))."\n";});

c3_test('Visible Likert submits stable option IDs while analytical values stay server-only',function()use($owner,&$owned){$d=json_decode(file_get_contents(__DIR__.'/assessment-editor/functional-fixture.json'),true);$d['id']='AE_SEC3_VALUES_'.bin2hex(random_bytes(8));$d['elements']=array($d['elements'][1]);$d['flow']['pages']=array();$d['flow']['metadata_profile']='basic';$q=&$d['elements'][0];$q['properties']['randomize_options']=true;foreach($q['options']as$i=>&$option)$option['value']=891001+$i;unset($option,$q);$d=D::validate($d);R::save($d,0);$owned[]=$d['id'];$v=$owner->publish($d['id'],1);$id=$owner->assign($v['version_id'],array('kind'=>'WORDPRESS_USER','user_id'=>1))['execution_id'];$f=c3_view($id);$q=$f['definition']['elements'][0];c3_assert(count($q['options'])>1);foreach($q['options']as$option)c3_assert(!array_key_exists('value',$option));$r=c3_command($f,'partial',array($q['response_key']=>'NOT_AN_OPTION'));c3_assert($r['status']===400);$choice=$q['options'][0]['id'];$r=c3_command($f,'submit',array($q['response_key']=>$choice));c3_assert($r['status']===200,$r['body']);$expected=null;foreach($d['elements'][0]['options']as$option)if($option['id']===$choice)$expected=$option['value'];c3_assert($owner->export($id)['rows'][0]['value']===$expected,'Scientific mapping lost');});
c3_test('Unresolved nested randomization exposes neither group nor question candidates',function()use($owner,&$owned){$x=c3_new('V3');$raw=$owner->view($x['id']);$d=$raw['definition'];$random=&$d['elements'][2];$child=$random['children'][0];$group=array('id'=>'SEC3_GROUP','type'=>'group','response_key'=>null,'properties'=>array('label'=>'SEC3_SECRET_GROUP'),'options'=>array(),'children'=>array($child));$random['children'][0]=$group;unset($random);$d['id']='AE_SEC3_NESTED_'.bin2hex(random_bytes(8));$d['flow']['pages']=array();$d=D::validate($d);R::save($d,0);$owned[]=$d['id'];$v=$owner->publish($d['id'],1);$id=$owner->assign($v['version_id'],array('kind'=>'WORDPRESS_USER','user_id'=>1))['execution_id'];$record=EIPSI\AssessmentEditor\Randomization::lazy(time()*1000);$owner->store->update('executions',array('metadata_json'=>D::json(array('randomization'=>$record))),$owner->store->prepare('id=%s',$id));$f=c3_view($id);c3_assert(strpos(D::json($f),'SEC3_SECRET_')===false);c3_assert(!json_decode($owner->store->find('executions',$id)['metadata_json'],true)['randomization']['blocks']);$r=c3_command($f,'next');c3_assert($r['status']===200,$r['body']);$record=json_decode($owner->store->find('executions',$id)['metadata_json'],true)['randomization'];$order=$record['blocks']['EL_RANDOM_TEST']['order'];$body=D::json($r['json']['data']);foreach($d['elements'][2]['children']as$c)c3_assert((strpos($body,$c['properties']['label'])!==false)===in_array($c['id'],$order,true));});

c3_test('Logical entry at a matrix row preserves later questions without exposing its prefix',function(){$x=c3_new();$f=c3_view($x['id']);$d=json_decode(file_get_contents(__DIR__.'/assessment-editor/functional-fixture.json'),true);$later=$d['elements'][0];$later['id']='SEC3_AFTER_MATRIX';$later['response_key']='SEC3_AFTER_MATRIX_RESPONSE';$later['properties']['variable_name']='after_matrix';$d['elements']=array($d['elements'][0],$d['elements'][2],$later);$d['flow']['pages']=array();$d=D::validate($d);$f['definition']=$d;$f['randomization']=null;$f['logical_entry_question']=$d['elements'][1]['properties']['matrix_rows'][1]['id'];$p=N\EffectiveAssessmentProjection::frame($f);$ids=array_column($p['definition']['elements'],'id');c3_assert(!in_array($d['elements'][0]['id'],$ids,true));c3_assert(in_array('SEC3_AFTER_MATRIX',$ids,true),'Entry removed questions after matrix target');c3_assert(count($p['definition']['elements'][0]['properties']['matrix_rows'])===count($d['elements'][1]['properties']['matrix_rows'])-1);});

c3_test('Previously visited future page never prefetches a changed responsive candidate',function()use($owner){$x=c3_new();$raw=$owner->view($x['id']);$raw['metadata']['pages'][$raw['definition']['flow']['pages'][1]['id']]=array('presented_at'=>1000);$old=$raw['randomization']['blocks']['EL_RANDOM_TEST']['order'][0];$next=null;foreach($x['definition']['elements'][2]['children']as$c)if($c['id']!==$old){$next=$c['id'];break;}$raw['randomization']['blocks']['EL_RANDOM_TEST']['order']=array($next);$raw['randomization']['blocks']['EL_RANDOM_TEST']['selected']=array($next);$p=N\EffectiveAssessmentProjection::frame($raw);c3_assert(strpos(D::json($p),'SEC3_SECRET_')===false,'Revised future content leaked through history');c3_assert($p['page']===0);});
